test("numbering per period scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.exportCsv(pg_uma)).toBe("name,grade,retired-from,due-total\nBen,A,,0.00\nCam,C,,0.00\nAda,B,,0.00\n");
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "3.33", "date": "2026-02-25"}));
  const c_cam_1 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "25.00", "date": "2026-03-05"}));
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.claimAction(pg_wes, c_cam_0, "open")).toBe(true);
  expect(await ui.editPerson(pg_wes, p_ada, {"grade": "C", "gradeFrom": "2026-02-25"})).toBe(true);
  expect(await ui.setRate(pg_wes, {"grade": "B", "pct": "20.00", "from": "2026-03-01"})).toBe(true);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("3.33");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("2.50");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("3.33");
  await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("1.00");
  expect(await ui.statement(pg_wes, p_cam)).toBe(true);
  const c_ben_0 = ui.must(await ui.addClaim(pg_wes, p_ben, {"amount": "0.40"}));
  await ui.refresh(pg_uma);
  expect(await ui.claimAction(pg_uma, c_cam_0, "settle")).toBe(true);
  const c_cam_2 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "-4.00", "corrects": "X-1"}));
  const c_cam_3 = ui.must(await ui.addClaimTwice(pg_uma, p_cam, {"amount": "99.95", "date": "2026-04-02"}));
  expect(await ui.claimCount(pg_uma, p_cam)).toBe(4);
  expect(await ui.claimAction(pg_uma, c_cam_1, "open")).toBe(true);
  const c_cam_4 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.35", "date": "2026-04-02"}));
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("28.33");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("3.50");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_4).getByTestId("claim-due")).toHaveText("1.04");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_4).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_4).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_3).getByTestId("claim-due")).toHaveText("10.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_3).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_3).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("summary-grade-B-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("summary-grade-B-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("summary-grade-C-count")).toHaveText("2");
  await expect(pg_uma.getByTestId("summary-grade-C-due-total")).toHaveText("3.50");
  await expect(pg_uma.getByTestId("summary-period-P1-due-total")).toHaveText("2.50");
  await expect(pg_uma.getByTestId("summary-period-P2-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("summary-status-DRAFT-count")).toHaveText("5");
  await expect(pg_uma.getByTestId("summary-status-OPEN-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("summary-status-PENDING-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("summary-status-SETTLED-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("summary-status-VOID-count")).toHaveText("0");
  await ui.expectAudit(sheet, [
    `ROLE_SET sheet=${sheet} by=uma user=wes role=steward`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=clerk-limit value=1.50`,
