import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useUser } from '../session/useUser';
import { ROLES, rolesKey, rolesQuery, settingsKey, settingsQuery } from './settingsQuery';
import type { Role, RoleName, Settings as SheetSettings, SettingsChange } from './settingsQuery';

const AMOUNT = /^\d{1,9}(\.\d{1,2})?$/;
const DAYS = /^\d{1,4}$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

const isDate = (d: string) => DATE.test(d) && new Date(`${d}T00:00:00Z`).toISOString().slice(0, 10) === d;

/** The sheet's settings — the clerk limit a clerk may settle up to (blank: no limit) and the floor a
 *  claim's live due is at least, and the terms (days after its date a claim is due by) and the late percent (what an overdue claim gains per full 30 days) — and the form
 *  they are saved through. A blank floor, terms or late percent is left as it is, and so is a blank clerk
 *  limit saved with any of them. The policy date decides how a claim's figures round (blank: the sheet's
 *  today). A save with every field blank clears whichever of the clerk limit and the policy date was last
 *  worked in (the clerk limit unless it was the policy date). */
function Settings({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const settings = useQuery(settingsQuery(sheetId));
  const [limit, setLimit] = useState('');
  const [floor, setFloor] = useState('');
  const [terms, setTerms] = useState('');
  const [latePct, setLatePct] = useState('');
  const [policyDate, setPolicyDate] = useState('');
  const [blank, setBlank] = useState<'clerkLimit' | 'policyDate'>('clerkLimit');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: SettingsChange) =>
      putJson<SheetSettings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) });
      setLimit('');
      setFloor('');
      setTerms('');
      setLatePct('');
      setPolicyDate('');
    },
    onError: () => setError('The settings could not be saved.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const l = limit.trim();
    if (l !== '' && !AMOUNT.test(l)) {
      setError('The clerk limit must be an amount of 0.00 or more, with up to two decimals.');
      return;
    }
    const f = floor.trim();
    if (f !== '' && !AMOUNT.test(f)) {
      setError('The floor must be an amount of 0.00 or more, with up to two decimals.');
      return;
    }
    const t = terms.trim();
    if (t !== '' && !DAYS.test(t)) {
      setError('The terms must be a whole number of days, 0 or more.');
      return;
    }
    const p = latePct.trim();
    if (p !== '' && !AMOUNT.test(p)) {
      setError('The late percent must be a percent of 0.00 or more, with up to two decimals.');
      return;
    }
    const d = policyDate.trim();
    if (d !== '' && !isDate(d)) {
      setError('The policy date must be a date (yyyy-mm-dd).');
      return;
    }
    const body: SettingsChange = {};
    const none = l === '' && f === '' && t === '' && p === '' && d === '';
    if (l !== '' || (none && blank === 'clerkLimit')) body.clerkLimit = l;
    if (d !== '' || (none && blank === 'policyDate')) body.policyDate = d;
    if (f !== '') body.floor = f;
    if (t !== '') body.terms = t;
    if (p !== '') body.latePct = p;
    once(() => save.mutateAsync(body));
  };

  return (
    <section data-testid="settings">
      <h3>Settings</h3>
      <form data-testid="settings-form" onSubmit={submit}>
        <label>
          Clerk limit{' '}
          <input
            data-testid="setting-clerk-limit"
            placeholder="no limit"
            value={limit}
            onFocus={() => setBlank('clerkLimit')}
            onChange={(e) => {
              setLimit(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Floor{' '}
          <input
            data-testid="setting-floor"
            placeholder="unchanged"
            value={floor}
            onChange={(e) => {
              setFloor(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Terms (days){' '}
          <input
            data-testid="setting-terms"
            placeholder="unchanged"
            value={terms}
            onChange={(e) => {
              setTerms(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Late percent{' '}
          <input
            data-testid="setting-late-pct"
            placeholder="unchanged"
            value={latePct}
            onChange={(e) => {
              setLatePct(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Policy date{' '}
          <input
            data-testid="setting-policy-date"
            placeholder="sheet's today"
            value={policyDate}
            onFocus={() => setBlank('policyDate')}
            onChange={(e) => {
              setPolicyDate(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {error && <p data-testid="settings-error">{error}</p>}
      </form>
      {settings.isError && <p data-testid="settings-load-error">Could not load the settings.</p>}
      <p>
        Clerk limit in force: <span data-testid="setting-clerk-limit-current">{settings.data?.clerkLimit ?? ''}</span>
      </p>
      <p>
        Floor in force: <span data-testid="setting-floor-current">{settings.data?.floor ?? ''}</span>
      </p>
      <p>
        Terms in force: <span data-testid="setting-terms-current">{settings.data?.terms ?? ''}</span>
      </p>
      <p>
        Late percent in force: <span data-testid="setting-late-pct-current">{settings.data?.latePct ?? ''}</span>
      </p>
      <p>
        Policy date in force: <span data-testid="setting-policy-date-current">{settings.data?.policyDate ?? ''}</span>
      </p>
    </section>
  );
}

/** The roles the sheet gives user names (any name not listed is a clerk), and the form a role is
 *  set through. */
function Roles({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const roles = useQuery(rolesQuery(sheetId));
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: Role) =>
      putJson<Role>(
        `/api/sheets/${encodeURIComponent(sheetId)}/roles/${encodeURIComponent(body.user)}`,
        { role: body.role },
        user,
      ),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: rolesKey(sheetId) });
      setName('');
      setRole('');
    },
    onError: () => setError('The role could not be set.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const n = name.trim();
    const r = role.trim();
    if (n === '') {
      setError('A user name is needed.');
      return;
    }
    if (!ROLES.includes(r as RoleName)) {
      setError('The role must be clerk or steward.');
      return;
    }
    once(() => save.mutateAsync({ user: n, role: r as RoleName }));
  };

  return (
    <section data-testid="roles">
      <h3>Roles</h3>
      <form data-testid="role-form" onSubmit={submit}>
        <label>
          User{' '}
          <input
            data-testid="role-form-user"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Role{' '}
          <input
            data-testid="role-form-role"
            placeholder="clerk or steward"
            list="role-names"
            value={role}
            onChange={(e) => {
              setRole(e.target.value);
              setError('');
            }}
          />
          <datalist id="role-names">
            {ROLES.map((r) => (
              <option key={r} value={r} />
            ))}
          </datalist>
        </label>{' '}
        <button type="submit" data-testid="role-form-submit" disabled={save.isPending}>
          Set role
        </button>
        {error && <p data-testid="role-form-error">{error}</p>}
      </form>
      {roles.isError && <p data-testid="roles-load-error">Could not load the roles.</p>}
      <table data-testid="roles-list">
        <tbody>
          {(roles.data ?? []).map((r) => (
            <tr key={r.user} data-testid={`role-row-${r.user}`}>
              <td data-testid="role-user">{r.user}</td>
              <td data-testid="role-value">{r.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

// Keyed by sheet, so a typed value or an error never carries over to another sheet.
export const contribution = SheetPanel.fill({
  order: 6,
  Component: ({ sheetId }) => (
    <>
      <Settings key={`settings-${sheetId}`} sheetId={sheetId} />
      <Roles key={`roles-${sheetId}`} sheetId={sheetId} />
    </>
  ),
});
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import type { Late } from '../rates/ratesQuery';
import { claimsQuery } from '../claims/claimsQuery';

/** `clerkLimit` has two decimals ("1.50"), or is "" when there is no limit; `floor` has two decimals;
 *  `terms` is a whole number of days ("14"); `latePct` is a percent with two decimals ("0.00");
 *  `policyDate` is yyyy-mm-dd, or "" when there is none (the sheet's today is the policy date). */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string };

/** What the request carries: a setting left out (or blank, for the floor, terms and late percent) is left as it is; a blank policy date is none. */
export type SettingsChange = { clerkLimit?: string; floor?: string; terms?: string; latePct?: string; policyDate?: string };

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days. */
export const DEFAULT_TERMS = '14';

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

export type RoleName = 'clerk' | 'steward';

/** The role a sheet gives a user name; a name with no entry is a clerk. */
export type Role = { user: string; role: RoleName };

export const ROLES: RoleName[] = ['clerk', 'steward'];

/** Under the sheet's key, so re-loading the sheet re-reads its settings and roles. */
export const settingsKey = (sheetId: string) => [...sheetKey(sheetId), 'settings'] as const;
export const rolesKey = (sheetId: string) => [...sheetKey(sheetId), 'roles'] as const;

export const settingsQuery = (sheetId: string) => ({
  queryKey: settingsKey(sheetId),
  queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
});

/** The sheet's floor: what a claim's live due is at least. */
export function useFloor(sheetId: string): string {
  return useQuery(settingsQuery(sheetId)).data?.floor ?? DEFAULT_FLOOR;
}

/** The sheet's terms in days: how long after its date a claim is due by. */
export function useTerms(sheetId: string): number {
  return Number(useQuery(settingsQuery(sheetId)).data?.terms ?? DEFAULT_TERMS);
}

/** The sheet's late percent: what an overdue claim gains of its figure for every full 30 days it is overdue. */
export function useLatePct(sheetId: string): string {
  return useQuery(settingsQuery(sheetId)).data?.latePct ?? DEFAULT_LATE_PCT;
}

/** The sheet's policy date (yyyy-mm-dd): the one set, or the sheet's today when there is none. */
export function usePolicyDate(sheetId: string): string {
  const today = useSheetToday(sheetId);
  return useQuery(settingsQuery(sheetId)).data?.policyDate || today;
}

/** What a claim's late charge and its rounding depend on, as the sheet has it now. */
export function useLate(sheetId: string): Late {
  return {
    today: useSheetToday(sheetId),
    terms: useTerms(sheetId),
    pct: useLatePct(sheetId),
    policy: usePolicyDate(sheetId),
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
  };
}

export const rolesQuery = (sheetId: string) => ({
  queryKey: rolesKey(sheetId),
  queryFn: () => getJson<Role[]>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`),
});

